1	/**
2	 * runs.thread (flat ThreadEntry[]) → assistant-ui ThreadMessageLike[].
3	 *
4	 * Grouping rule: a consecutive run of assistant/tool/agent entries is ONE
5	 * assistant message whose content interleaves text parts and tool-call
6	 * parts (matching CC's actual turn structure). tool_result entries attach
7	 * to their tool-call part by tool_use_id. user/system entries are their
8	 * own messages; system carries `kind` in metadata.custom so the renderer
9	 * can color errors / stuck notices.
10	 */
11	
12	import type { ThreadMessageLike } from "@assistant-ui/react";
13	import type { ThreadEntry } from "../../api";
14	
15	type ToolCallPart = {
