17	  toolCallId?: string;
18	  toolName: string;
19	  argsText?: string;
20	  result?: unknown;
21	  isError?: boolean;
22	};
23	
24	type TextPart = { type: "text"; text: string };
25	type Part = TextPart | ToolCallPart;
26	
27	function entryDate(e: ThreadEntry): Date | undefined {
28	  const t = new Date(e.ts).getTime();
29	  return Number.isNaN(t) ? undefined : new Date(t);
30	}
