32	export function mapThreadToMessages(
33	  thread: ThreadEntry[],
34	): ThreadMessageLike[] {
35	  const messages: ThreadMessageLike[] = [];
36	  let openParts: Part[] | null = null;
37	  let openId = "";
38	  let openAt: Date | undefined;
39	
40	  const closeOpen = () => {
41	    if (openParts && openParts.length > 0) {
42	      messages.push({
43	        role: "assistant",
44	        content: openParts as ThreadMessageLike["content"],
45	        id: openId,
46	        createdAt: openAt,
47	      } as ThreadMessageLike);
48	    }
49	    openParts = null;
50	  };
51	
52	  thread.forEach((e, i) => {
53	    const content = String(e.content ?? "");
